const group = new THREE.Group();
const hub = new THREE.CylinderGeometry(0.1, 0.1, 0.1, 32);
const hubMesh = new THREE.Mesh(hub);
group.add(hubMesh);
for(let i=0; i<4; i++) {
  const blade = new THREE.BoxGeometry(1.2, 0.01, 0.2);
  const bladeMesh = new THREE.Mesh(blade);
  bladeMesh.rotation.y = (i * Math.PI) / 2;
  bladeMesh.position.x = Math.cos(bladeMesh.rotation.y) * 0.6;
  bladeMesh.position.z = Math.sin(bladeMesh.rotation.y) * 0.6;
  group.add(bladeMesh);
}
return group;

const group = new THREE.Group();
const ring = new THREE.TorusGeometry(1, 0.05, 16, 100);
const mat = new THREE.MeshStandardMaterial({color: 0xffd700, metalness: 1, roughness: 0.2});
const mesh = new THREE.Mesh(ring, mat);
mesh.rotation.x = Math.PI/2;
group.add(mesh);
for(let i=0; i<8; i++) {
  const crystal = new THREE.SphereGeometry(0.1, 8, 8);
  const cMesh = new THREE.Mesh(crystal, new THREE.MeshStandardMaterial({color: 0xffffff, transparent: true, opacity: 0.8}));
  cMesh.position.set(Math.cos(i*Math.PI/4), -0.2, Math.sin(i*Math.PI/4));
  group.add(cMesh);
}
return group;
